\draw[black,thick,->] (O)--(A) node[midway,below] {$\underset{\sim}{x}$};
\draw[black,thick,->] (O)--(B) node[midway,left] {$\underset{\sim}{y}$};
\draw[black] (A)--(B); \fill[black] (N) circle (1.5pt);
\path (O) node[below left] {$O$} (A) node[below right] {$A$} (B) node[above] {$B$} (N) node[above right] {$N$};
\end{tikzpicture}
[/tikz]

